const input = $json;
const body = input.body || input || {};
const event = body.event || '';
if(!event) {
  throw new Error('Webhook payload missing event.');
}
if(event !== 'recording.completed') {
  throw new Error('Ignored event: ' + event + '. This workflow expects recording.completed.');
}
const obj = body.payload && body.payload.object ? body.payload.object : (body.object || null);
if(!obj) {
  throw new Error('Webhook payload does not contain expected payload.object; ensure Zoom webhook is configured for recording.completed and sends the full payload.');
}
const files = obj.recording_files || [];
if(!files || files.length === 0) {
  throw new Error('No recording_files found in payload; recording might not yet be processed by Zoom. The workflow will stop.');
}
let recordingUrl = null;
for(const f of files){
  const ft = (f.file_type || f.recording_type || '').toString().toLowerCase();
  if(['mp4','m4a','audio_only','audio'].some(t => ft.includes(t))){
    recordingUrl = f.download_url || f.file_url || f.content_url || f.url;
    break;
  }
}
recordingUrl = recordingUrl || (files[0].download_url || files[0].file_url);
if(!recordingUrl){
  throw new Error('No downloadable URL found for recording files.');
}
const organizerEmail = obj.host_email || obj.user_email || obj.owner_email || null;
const meetingTopic = obj.topic || obj.meeting_topic || '';
const meetingStart = obj.start_time || null;
const defaultPrompt = "Tu es un assistant qui produit un compte-rendu clair et structuré pour une réunion. Produis 1) un titre, 2) une date, 3) un résumé de 3-5 lignes, 4) une section Décisions, 5) une section Actions (avec responsables si identifiables), 6) une liste Participants. Ensuite ajoute la transcription complète dans un bloc toggle. Répond en français.";
return [{
  json: {
    recordingUrl,
    organizerEmail,
    meetingTopic,
    meetingStart,
    userPrompt: (body.userPrompt || defaultPrompt),
    sendEmail: (typeof body.sendEmail !== 'undefined') ? !!body.sendEmail : true,
    emailProvider: (body.emailProvider || 'gmail'),
    notionDatabaseId: (body.notionDatabaseId || '')
  }
}];

const items = $input.all();
if(!items || items.length === 0) {
  throw new Error('No items after download step.');
}
const item = items[0];
if(!item.binary || !item.binary.recording_file){
  throw new Error('Downloaded file missing from binary.recording_file — likely the download failed or file not yet available (Zoom may return a 403 until processing is complete).');
}
let size = 0;
try{
  const data = item.binary.recording_file.data;
  if(Buffer.isBuffer(data)) size = data.length;
  else if(typeof data === 'string') size = Buffer.from(data,'base64').length;
  else if(data && data.length) size = data.length;
} catch(error){
  throw new Error('Unable to determine downloaded file size: ' + error.message);
}
item.json.fileSize = size;
const limit = 25 * 1024 * 1024;
item.json.fileTooLarge = size > limit;
return [item];

const items = $input.all();
const results = [];
for(const item of items){
  const err = item.json.error || item.json;
  const status = err.statusCode || err.status || err.httpCode || 'unknown';
  const message = err.message || err.error || 'Download failed';
  let diagnostic = 'Erreur de téléchargement inconnue.';
  if(status === 403 || status === '403'){
    diagnostic = 'Zoom a retourné 403 : le fichier n\'est probablement pas encore prêt (réunions longues) OU le token OAuth est expiré / scope cloud_recording:read:admin manquant. Vérifiez le scope du credential Zoom et relancez après quelques minutes.';
  } else if(status === 404 || status === '404'){
    diagnostic = 'URL de téléchargement introuvable (404). Le fichier a peut-être été supprimé côté Zoom.';
  } else if(status === 401 || status === '401'){
    diagnostic = 'Non autorisé (401) : le token OAuth Zoom est invalide ou expiré. Vérifiez le credential Zoom OAuth2.';
  }
  results.push({
    json: {
      status: 'download_error',
      httpStatus: status,
      errorMessage: message,
      diagnostic,
      recordingUrl: item.json.recordingUrl || null
    }
  });
}
return results;
